export type SlaStatus = "ok" | "warning" | "breached";

export function getSlaStatus(slaDueAt: string, now = "2026-04-10T12:00:00Z"): SlaStatus {
  const dueMs = new Date(slaDueAt).getTime();
  const nowMs = new Date(now).getTime();
  const diffHours = (dueMs - nowMs) / (1000 * 60 * 60);
  if (diffHours < 0) return "breached";
  if (diffHours < 24) return "warning";
  return "ok";
}

